import {Game,W,H,BOSSES,MODES,UPGRADES,STAGE_COUNT,xpRequired} from './core.js';
import {Renderer} from './render.js';
import {currentUser,registerAccount,loginAccount,logoutAccount} from './auth.js';
import {emptyProgress,parseStageProgress,recordClear,highestStage,starsForHealth} from './progress.js';
const $=id=>document.getElementById(id),KEY='redline-protocol-v2',CPKEY='redline-campaign-checkpoint-v2';
let checkpointState=null,stageProgress=emptyProgress(),profile=currentUser(),recordedStage=-1;
const PROGRESSKEY='shatter-stages-v1';
let accountMode='login',accountBusy=false,accountResume=false,stagesResume=false,stageMode='challenge';
const scoped=key=>profile?key+'@'+profile.id:key;
const getStore=key=>localStorage.getItem(scoped(key));
const putStore=(key,value)=>localStorage.setItem(scoped(key),value);
const delStore=key=>localStorage.removeItem(scoped(key));
let selected='challenge',game=new Game('challenge',0,1),active=false,paused=false,autoFire=true,muted=true,audio=null,last=0,accumulator=0,uiTimer=0,target=null,pointer=null,pointerOrigin=null,helpResume=false,runStored=false,lastSound=0;
let records={challenge:{best:0,clears:0,fastest:null},nightmare:{best:0,clears:0,fastest:null}};
const keys=new Set(),renderer=new Renderer($('gameCanvas'));
function loadProfileData(){records={challenge:{best:0,clears:0,fastest:null},nightmare:{best:0,clears:0,fastest:null}};checkpointState=null;stageProgress=emptyProgress();muted=true;try{const cp=JSON.parse(getStore(CPKEY)||'null');if(cp){Game.fromCheckpoint(cp);checkpointState=cp;}}catch{}try{const raw=JSON.parse(getStore(KEY)||'null');if(raw&&raw.version===1){for(const m of ['challenge','nightmare']){const r=raw.records?.[m];if(r&&Number.isFinite(r.best)&&r.best>=0&&Number.isInteger(r.clears)&&r.clears>=0&&(r.fastest===null||Number.isFinite(r.fastest)&&r.fastest>0))records[m]={best:r.best,clears:r.clears,fastest:r.fastest};}muted=raw.muted!==false;}}catch{}try{const raw=getStore(PROGRESSKEY);if(raw)stageProgress=parseStageProgress(raw);}catch{}if(checkpointState)stageProgress[checkpointState.mode].entries[checkpointState.stage]=checkpointState;}
loadProfileData();
const clock=t=>{const n=Math.floor(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
function save(){try{putStore(KEY,JSON.stringify({version:1,records,muted}));$('saveStatus').textContent='● 纪录已保存在此浏览器';}catch{$('saveStatus').textContent='此浏览器暂时无法保存纪录';}}
function sound(frequency,duration=.07,volume=.018,slide=0){if(muted)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type='triangle';o.frequency.setValueAtTime(frequency,t);if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+duration);}catch{}}
function input(){return {left:keys.has('arrowleft')||keys.has('a'),right:keys.has('arrowright')||keys.has('d'),up:keys.has('arrowup')||keys.has('w'),down:keys.has('arrowdown')||keys.has('s'),slow:keys.has('shift'),fire:autoFire||keys.has(' ')||keys.has('j'),target};}
function clearInput(){keys.clear();target=null;pointer=null;pointerOrigin=null;}
function overlays(id=null){for(const n of ['menuOverlay','pauseOverlay','resultOverlay','breakOverlay','levelOverlay'])$(n).hidden=n!==id;}
function focusGame(){$('gameCanvas').focus({preventScroll:true});}
function showArena(){const r=$('arena').getBoundingClientRect();if(r.bottom+65>innerHeight||r.top<0)$('arena').scrollIntoView({block:'center',behavior:'instant'});}
function saveCheckpoint(){if(game.mode==='practice')return;checkpointState=game.checkpoint();stageProgress[game.mode].entries[game.bossIndex]=checkpointState;saveStageProgress();try{putStore(CPKEY,JSON.stringify(checkpointState));$('saveStatus').textContent='● 第 '+(game.bossIndex+1)+' 关关首已保存';}catch{$('saveStatus').textContent='此浏览器暂时无法保存进度';}renderContinue();}
function renderContinue(){$('continueRunBtn').hidden=!checkpointState;$('continueRunBtn').textContent=checkpointState?`继续第 ${checkpointState.stage+1} / 30 关 · Lv.${checkpointState.level}（关首存档）`:'';}
function activate(){recordedStage=-1;active=true;paused=false;runStored=false;last=performance.now();accumulator=0;clearInput();overlays();$('arena').classList.add('in-flight');focusGame();showArena();hud();sound(220,.18,.03,880);}
function start(mode=selected,boss=0){game=new Game(mode,mode==='practice'?boss:0);if(mode!=='practice')saveCheckpoint();activate();}
function continueRun(){if(!checkpointState)return;game=Game.fromCheckpoint(checkpointState);activate();}
function pause(){if(!active||paused||game.state!=='playing')return;paused=true;clearInput();overlays('pauseOverlay');hud();}
function resume(){if(!active)return;if(['intermission','upgrade'].includes(game.state)){paused=false;if(game.state==='upgrade')levelUp();else{renderUpgrades();overlays('breakOverlay');}hud();return;}if(game.state!=='playing')return;paused=false;last=performance.now();accumulator=0;overlays();focusGame();hud();}
function menu(){paused=true;clearInput();$('resumeMenuBtn').hidden=!active||!['playing','intermission','upgrade'].includes(game.state);$('resumeMenuBtn').textContent=game.state==='playing'?'← 继续当前战斗':'← 返回强化选择';renderContinue();overlays('menuOverlay');hud();}
function finish(){if(runStored)return;if(game.state==='won'&&game.mode!=='practice')recordMissionClear();$('resultStars').textContent=game.state==='won'&&game.mode!=='practice'?'★'.repeat(starsForHealth(game.player.hp,game.player.maxHp))+'☆'.repeat(3-starsForHealth(game.player.hp,game.player.maxHp)):'';runStored=true;const won=game.state==='won',practice=game.mode==='practice';if(!practice){const r=records[game.mode];r.best=Math.max(r.best,game.score);if(won){r.clears++;r.fastest=Math.min(r.fastest??Infinity,game.time);checkpointState=null;try{delStore(CPKEY);}catch{}renderContinue();}save();}
 $('resultCode').textContent=practice?'TRAINING COMPLETE / 练习完成':won?'PROTOCOL BROKEN / 协议突破':'LINK LOST / 链路中断';
 $('resultTitle').innerHTML=practice?'这一战，已掌握。<br><em>准备迎接挑战。</em>':won?'你穿过了赤线。<br><em>漂亮的一次突破。</em>':'距离突破，<br><em>还差一点。</em>';
 $('resultCopy').textContent=practice?`练习已完成，累计复位 ${game.deaths} 次。现在可以尝试正式挑战。`:won?`${MODES[game.mode].label}通关 · 击破 ${game.kills} 个 Boss · 受到 ${game.hits} 次伤害。`:game.encounter==="boss"?`止步于「${BOSSES[game.bossIndex].name}」第 ${game.boss.phase+1} 阶段。${BOSSES[game.bossIndex].tip}`:`止步于第 ${game.bossIndex+1} 关的小型机群（第 ${game.wave} 批）。留意来袭敌机的瞄准弹，危急时冲刺或清屏。`;
 $('resultScore').textContent=practice?'练习':game.score.toLocaleString('zh-CN');$('resultTime').textContent=clock(game.time);$('resultGraze').textContent=game.grazes;$('retryBtn').firstChild.textContent=practice?'重新练习 ':won?'开始新战役 ':'从本关关首重试 ';overlays('resultOverlay');clearInput();hud();}
function upgradePreview(u){const s=game.stats;switch(u.id){case'pellets':return `主炮弹数 ${s.pellets} → ${s.pellets+2} 枚 / 轮`;case'damage':return `单发 ${s.damage.toFixed(1)} → ${(s.damage+2.8).toFixed(1)}`;case'rapid':return `射击间隔 ${(s.fireInterval*1000).toFixed(0)} → ${(s.fireInterval*.9*1000).toFixed(0)} ms`;case'spread':return `斜向弹 ${s.sideShots} → ${s.sideShots+2} 枚 / 轮`;case'drone':return `追踪卫星 ${s.drones} → ${s.drones+1} 架`;case'dash':return `冲刺冷却 ${s.dashCooldown.toFixed(2)} → ${(s.dashCooldown*.82).toFixed(2)} s`;case'armor':return `装甲上限 ${game.player.maxHp} → ${game.player.maxHp+1} 格`;case'reactor':return `充能 ${s.grazeTarget} → ${Math.max(6,s.grazeTarget-3)} 次 · 清屏 ${s.bombDamage} → ${s.bombDamage+120}`;case'barrier':return `每关护盾 ${s.barrier} → ${s.barrier+1} 层`;default:return '达到强化上限后，仍可选择补给';}}
function levelUp(){$('pilotLevel').textContent='LV.'+game.level;$('levelChoices').replaceChildren(...game.choices.map((id,i)=>{const u=UPGRADES.find(x=>x.id===id),b=document.createElement('button');b.className='upgrade-card';b.dataset.upgrade=id;b.innerHTML=`<div class="upgrade-card-top"><span>${u.icon}</span><small>${u.type} / LV.${(game.upgrades[id]||0)+1}</small><kbd>${i+1}</kbd></div><h3>${u.name}</h3><p>${u.desc}</p><div class="upgrade-preview">${upgradePreview(u)}</div>`;b.onclick=()=>chooseUpgrade(id);return b;}));clearInput();overlays('levelOverlay');hud();}
function renderUpgrades(){const chosen=game.selectedUpgrade;$('upgradeChoices').replaceChildren(...game.choices.map((id,i)=>{const u=UPGRADES.find(x=>x.id===id),b=document.createElement('button');b.className='upgrade-card'+(chosen===id?' chosen':'');b.dataset.upgrade=id;b.disabled=!!chosen;b.setAttribute('aria-pressed',String(chosen===id));b.innerHTML=`<div class="upgrade-card-top"><span>${u.icon}</span><small>${u.type} / LV.${(game.upgrades[id]||0)+(chosen===id?0:1)}</small><kbd>${i+1}</kbd></div><h3>${u.name}</h3><p>${u.desc}</p><div class="upgrade-preview">${chosen===id?'✓ 已装载，本局持续生效':chosen?'本次未选择':upgradePreview(u)}</div>`;b.onclick=()=>chooseUpgrade(id);return b;}));$('nextBtn').disabled=!chosen;$('nextBtn').innerHTML=chosen?'携带强化，接入下一战 <span>→</span>':'先选择一项强化 <span>→</span>';$('upgradeStatus').textContent=chosen?'已装载「'+UPGRADES.find(u=>u.id===chosen).name+'」。准备好后进入下一关。':'选择期间战斗与计时均已停止。强化可叠加，达到上限后不再出现。';}
function chooseUpgrade(id){if(!game.chooseUpgrade(id))return;handleEvents();if(game.state==='intermission'){renderUpgrades();$('nextBtn').focus({preventScroll:true});}else if(game.state==='upgrade')levelUp();else{overlays();last=performance.now();accumulator=0;focusGame();if(document.hidden)pause();}hud();}
function stageClear(){const stars=recordMissionClear();$('clearStars').textContent='★'.repeat(stars)+'☆'.repeat(3-stars)+' · 剩余装甲 '+game.player.hp+'/'+game.player.maxHp;$('nextBossName').textContent=BOSSES[game.bossIndex+1].name;$('breakCopy').textContent='选择一项强化，效果持续到本局结束。重开挑战时重新构筑。';renderUpgrades();overlays('breakOverlay');clearInput();hud();}
function handleEvents(){const events=game.events.splice(0);for(const e of events){if(e.type==="levelup"){levelUp();sound(800,.25,.035,1300);}if(e.type==='upgrade')sound(500,.25,.03,1300);if(e.type==='barrier')sound(750,.18,.025,330);if(e.type==='dash')sound(230,.13,.025,1000);if(e.type==='bomb')sound(90,.45,.05,350);if(e.type==='hit')sound(140,.2,.04,45);if(e.type==='phase')sound(400,.2,.035,100);if(e.type==='charge')sound(600,.22,.025,1200);if(e.type==='warning'&&performance.now()-lastSound>500){lastSound=performance.now();sound(580,.08,.014);}if(e.type==='stageClear'){stageClear();sound(420,.35,.035,1100);}if(e.type==='win'||e.type==='lose'){finish();sound(e.type==='win'?550:160,.45,.04,e.type==='win'?1300:50);}}}
function dash(){if(!active||paused||document.querySelector('dialog[open]'))return;game.dash(input());handleEvents();hud();}
function bomb(){if(!active||paused||document.querySelector('dialog[open]'))return;game.bomb();handleEvents();hud();}
function hud(){const b=BOSSES[game.bossIndex],p=game.player,phase=game.boss.phase;document.documentElement.style.setProperty('--boss-color',b.color);$('modeTag').textContent=active?MODES[game.mode].label+(paused&&game.state==='playing'?' / 暂停':''):'待命 / STANDBY';$('stageTag').textContent=`遭遇 ${String(game.bossIndex+1).padStart(2,'0')} — 30`;$('bossCode').textContent=b.code;$('bossName').textContent=b.name;$('bossPhase').textContent='PHASE '+(phase+1)+' / 3';$('bossBar').style.width=Math.max(0,game.boss.hp/game.boss.maxHp*100)+'%';$('bossBar').style.background=b.color;$('bossHud').hidden=game.state==='won'||game.state==='intermission';$('hearts').innerHTML=Array.from({length:p.maxHp},(_,i)=>'<i class="heart'+(i>=p.hp?' empty':'')+'"></i>').join('');$('dashBar').style.width=(1-p.dashCd/game.stats.dashCooldown)*100+'%';$('dashLabel').innerHTML=p.dashCd>0?'冲刺冷却 '+p.dashCd.toFixed(1)+'s':'冲刺就绪 <kbd>X</kbd>';$('bombCount').textContent=String(p.bombs).padStart(2,'0');$('scoreValue').textContent=String(game.score).padStart(6,'0');$('timeValue').textContent=clock(game.time);$('grazeValue').textContent=String(game.grazes).padStart(3,'0');$('chargeValue').textContent=p.charge+' / '+game.stats.grazeTarget;$('chargeBar').style.width=p.charge/game.stats.grazeTarget*100+'%';$('targetIndex').textContent=String(game.bossIndex+1).padStart(2,'0')+' / 30';$('targetCode').textContent=b.code.split(' / ')[1];$('targetName').textContent=b.name;$('targetSymbol').textContent=['◇','✳','⬡'][b.pattern];$('targetSymbol').style.color=b.color;$('bossTip').textContent=b.tip;for(let i=0;i<3;i++)$('phase'+(i+1)).className=i===phase?'active':i<phase?'done':'';$('touchDash').disabled=p.dashCd>0||!active||paused||game.state!=='playing';$('touchBomb').disabled=p.bombs<=0||!active||paused||game.state!=='playing';$('autoBtn').setAttribute('aria-checked',String(autoFire));$('pauseBtn').setAttribute('aria-label',paused?'继续游戏':'暂停游戏');$('pauseBtn').textContent=paused?'▷':'Ⅱ';
 renderEncounter();renderBuild();const m=active&&game.mode!=='practice'?game.mode:selected,r=records[m];$('recordMode').textContent=MODES[m].label+' / BEST';$('recordScore').textContent=r.best?r.best.toLocaleString('zh-CN'):'—';$('recordHint').textContent=r.clears?`已通关 ${r.clears} 次 · 最快 ${clock(r.fastest)}`:'通关后的纪录，将成为下一次的目标。';
}
function renderEncounter(){const waves=game.encounter==='waves',warning=game.encounter==='warning',inFlight=game.state==='playing',names=waves?['侦察编队','突击编队','重装编队']:['链路启动','火力升级','过载协议'];$('waveHud').hidden=!(waves||warning)||!inFlight;$('bossHud').hidden=waves||warning||!inFlight;$('stageTag').textContent=`第 ${game.bossIndex+1} / 30 关 · `+(waves?`小怪 ${game.wave}/3`:warning?'Boss 接近':'关底 Boss');if(waves||warning){$('waveTitle').textContent=warning?'WARNING / 大型敌机接近':`小型机群 / 清扫 ${game.wave} — 3`;$('waveCounter').textContent=warning?'决战即将开始':`场上 ${game.enemies.length} 架 · 待入场 ${game.spawnRemaining} 架`;$('waveHint').textContent=warning?'机群已清扫，准备迎战关底 Boss':'击落小怪获得经验 · 每升一级选择强化';$('waveBar').style.width=(warning?100:((game.wave-1)+1-Math.min(1,(game.spawnRemaining+game.enemies.length)/game.waveQuota()))/3*100)+'%';$('waveHud').classList.toggle('incoming',warning);$('targetCode').textContent=warning?'BOSS INCOMING':'ENEMY SQUADRON';$('targetName').textContent=warning?'大型信号锁定':'敌方先遣机群';$('targetSymbol').textContent=warning?'⚠':'⋔';$('bossTip').textContent=warning?'大型敌机将在警报后进场。保持移动，留好冲刺和清屏弹。':'观察敌机下方的开火提示，从直线与扇形弹之间穿过。移动到目标下方持续开火。';}for(let i=0;i<3;i++){const node=$('phase'+(i+1));node.querySelector('b').textContent=names[i];if(waves)node.className=i===game.wave-1?'active':i<game.wave-1?'done':'';if(warning)node.className='done';}}
function renderBuild(){$('buildList').innerHTML=game.upgradeHistory.length?Object.entries(game.upgrades).map(([id,n])=>{const u=UPGRADES.find(x=>x.id===id);return `<span class="build-chip" title="${u.desc}">${u.icon} ${u.name} <b>Lv.${n}</b></span>`;}).join(''):'<span>击落小怪获得经验，每升一级选择强化。</span>';const s=game.stats;$('buildStats').textContent=`主炮 ${s.pellets} 发 × ${s.damage.toFixed(1)} · 攻速 ${(1/s.fireInterval).toFixed(1)} 轮/s · 冲刺 ${s.dashCooldown.toFixed(2)}s`+(s.barrier?' · 护盾 '+game.player.barrier+'/'+s.barrier:'');$('xpLevel').textContent='LV.'+game.level;$('xpText').textContent=game.xp+' / '+xpRequired(game.level)+' XP';$('xpBar').style.width=Math.min(100,game.xp/xpRequired(game.level)*100)+'%';$('enemyKills').textContent=game.enemyKills+' 架击落';}
function saveStageProgress(){try{putStore(PROGRESSKEY,JSON.stringify(stageProgress));}catch{$('saveStatus').textContent='关卡与星级暂时无法保存';}}
function recordMissionClear(){const stars=starsForHealth(game.player.hp,game.player.maxHp);if(game.mode==='practice'||recordedStage===game.bossIndex)return stars;recordedStage=game.bossIndex;recordClear(stageProgress,game.mode,game.bossIndex,game.player.hp,game.player.maxHp);saveStageProgress();return stars;}
function renderStages(){const data=stageProgress[stageMode],high=highestStage(stageProgress,stageMode);$('stageStarsTotal').textContent=data.records.reduce((n,r)=>n+(r?.stars||0),0)+' / 90 ★';document.querySelectorAll('[data-stage-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.stageMode===stageMode);b.onclick=()=>{stageMode=b.dataset.stageMode;renderStages();};});$('stageGrid').replaceChildren(...[0,1,2].map(chapter=>{const section=document.createElement('section'),h=document.createElement('h3'),grid=document.createElement('div');h.textContent=['第一战区 · 边界突破','第二战区 · 暗流纵深','第三战区 · 碎甲成原'][chapter];grid.className='stage-grid';for(let n=0;n<10;n++){const index=chapter*10+n,b=document.createElement('button'),r=data.records[index];b.className='stage-tile'+(r?' cleared':'');b.disabled=index>high;b.dataset.stage=index;b.setAttribute('aria-label',`第 ${index+1} 关 ${BOSSES[index].name}，${index>high?'尚未解锁':r?r.stars+' 星':'待挑战'}`);b.innerHTML=`<strong>${String(index+1).padStart(2,'0')}</strong><span>${BOSSES[index].name}</span><small>${index>high?'未解锁':r?'★'.repeat(r.stars)+'☆'.repeat(3-r.stars):'待挑战'}</small>`;b.onclick=()=>enterStage(index);grid.append(b);}section.append(h,grid);return section;}));}
function showStages(){stagesResume=active&&!paused&&game.state==='playing';if(stagesResume)pause();stageMode=active&&game.mode!=='practice'?game.mode:selected;renderStages();$('stageDialog').showModal();}
function closeStages(){$('stageDialog').close();if(stagesResume)resume();stagesResume=false;}
function enterStage(index){if(index>highestStage(stageProgress,stageMode))return;const data=stageProgress[stageMode],base=data.entries[index]||(checkpointState?.mode===stageMode?checkpointState:Object.values(data.entries).at(-1));game=base?Game.fromCheckpoint({...base,stage:index}):new Game(stageMode,index);stagesResume=false;$('stageDialog').close();saveCheckpoint();activate();}
function renderAccountBadge(){$('accountBtn').textContent=profile?profile.name:'注册 / 登录';$('accountBtn').title=profile?'本机账号：'+profile.name:'本机账号注册 / 登录';}
function renderAccount(){const signed=!!profile;$('accountTitle').textContent=signed?'飞行员档案':accountMode==='register'?'建立你的飞行员档案。':'欢迎回来，飞行员。';$('authTabs').hidden=signed;$('accountForm').hidden=signed;$('accountSummary').hidden=!signed;$('accountStatus').textContent='';$('accountWelcome').textContent=signed?'当前账号：'+profile.name+'。关卡、星级与战役进度独立保存。':'';$('registerNote').hidden=accountMode!=='register';$('accountSubmit').innerHTML=accountMode==='register'?'注册并进入游戏 <span>→</span>':'登录并载入进度 <span>→</span>';$('accountPassword').autocomplete=accountMode==='register'?'new-password':'current-password';document.querySelectorAll('[data-auth-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.authMode===accountMode));}
function showAccount(){accountResume=active&&!paused&&game.state==='playing';if(accountResume)pause();clearInput();renderAccount();$('accountDialog').showModal();}
function closeAccount(){if(accountBusy)return;$('accountDialog').close();$('accountPassword').value='';if(accountResume)resume();accountResume=false;}
function switchProfile(user,migrateGuest=false){profile=user;if(migrateGuest&&user){for(const key of [KEY,CPKEY,PROGRESSKEY]){try{const raw=localStorage.getItem(key);if(raw&&!getStore(key))putStore(key,raw);}catch{}}}loadProfileData();game=new Game('challenge',0,1);active=false;paused=false;recordedStage=-1;clearInput();overlays('menuOverlay');renderAccountBadge();renderContinue();updateSound();hud();}
async function submitAccount(e){e.preventDefault();if(accountBusy)return;accountBusy=true;$('accountSubmit').disabled=true;const name=$('accountName').value,password=$('accountPassword').value,migrate=accountMode==='register'&&!profile;try{const user=accountMode==='register'?await registerAccount(name,password):await loginAccount(name,password);accountResume=false;$('accountPassword').value='';$('accountDialog').close();switchProfile(user,migrate);}catch(error){$('accountStatus').textContent=error.message;}finally{accountBusy=false;$('accountSubmit').disabled=false;}}
function setMode(mode){if(!['challenge','nightmare'].includes(mode))return;selected=mode;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});hud();}
function updateSound(){$('soundBtn').setAttribute('aria-pressed',String(!muted));$('soundBtn').setAttribute('aria-label',muted?'开启音效':'关闭音效');$('soundBtn').title=muted?'开启音效':'关闭音效';$('soundBtn').style.opacity=muted?'.5':'1';}
function showHelp(){helpResume=active&&!paused&&game.state==='playing';if(helpResume)pause();clearInput();$('helpDialog').showModal();}
function closeHelp(){$('helpDialog').close();if(helpResume)resume();helpResume=false;}
$('startBtn').onclick=()=>start();$('practiceBtn').onclick=()=>start('practice',Number($('practiceBoss').value));$('resumeBtn').onclick=resume;$('resumeMenuBtn').onclick=resume;$('pauseMenuBtn').onclick=menu;$('resultMenuBtn').onclick=menu;$('menuBtn').onclick=menu;$('retryBtn').onclick=()=>game.mode!=="practice"&&checkpointState?continueRun():start(game.mode,game.startBoss);$('pauseBtn').onclick=()=>paused?resume():pause();$('nextBtn').onclick=()=>{if(game.nextBoss()){recordedStage=-1;saveCheckpoint();overlays();last=performance.now();accumulator=0;handleEvents();hud();focusGame();}};$('touchDash').onpointerdown=e=>{e.preventDefault();dash();};$('touchBomb').onpointerdown=e=>{e.preventDefault();bomb();};$('autoBtn').onclick=()=>{autoFire=!autoFire;hud();};$('helpBtn').onclick=showHelp;$('closeHelp').onclick=closeHelp;$('helpReady').onclick=closeHelp;$('helpDialog').addEventListener('cancel',e=>{e.preventDefault();closeHelp();});$('helpDialog').addEventListener('click',e=>{if(e.target!==$('helpDialog'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeHelp();});$('soundBtn').onclick=()=>{muted=!muted;updateSound();save();if(!muted)sound(660,.1);};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
document.addEventListener('keydown',e=>{if(e.target.matches('select,input,textarea')||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(['1','2','3'].includes(k)&&((!$("breakOverlay").hidden&&game.state==='intermission')||(!$("levelOverlay").hidden&&game.state==='upgrade'))){e.preventDefault();if(!e.repeat)chooseUpgrade(game.choices[Number(k)-1]);return;}if(['arrowup','arrowdown','arrowleft','arrowright',' ','shift','w','a','s','d','j','x','k','e','p','escape'].includes(k))e.preventDefault();if((k==='p'||k==='escape')&&!e.repeat){paused?resume():pause();return;}if(!active||paused||game.state!=='playing')return;keys.add(k);if(!e.repeat){if(k==='x'||k==='k')dash();if(k==='e')bomb();}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
const canvas=$('gameCanvas');function pointerTarget(e){const r=canvas.getBoundingClientRect();if(e.pointerType==='touch'){const origin=pointerOrigin||{x:e.clientX,y:e.clientY};target={x:Math.max(18,Math.min(W-18,(target?.x??game.player.x)+(e.clientX-origin.x)/r.width*W*1.25)),y:Math.max(175,Math.min(H-20,(target?.y??game.player.y)+(e.clientY-origin.y)/r.height*H*1.25)),touch:true};pointerOrigin={x:e.clientX,y:e.clientY};}else target={x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
canvas.addEventListener('pointerdown',e=>{if(!active||paused||game.state!=='playing')return;e.preventDefault();if(e.button===2){dash();return;}if(pointer!==null)return;pointer=e.pointerId;pointerOrigin={x:e.clientX,y:e.clientY};canvas.setPointerCapture(pointer);pointerTarget(e);focusGame();});canvas.addEventListener('pointermove',e=>{if(e.pointerId===pointer)pointerTarget(e);});const release=e=>{if(e.pointerId===pointer){target=null;pointer=null;pointerOrigin=null;}};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',release);canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('blur',()=>{clearInput();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();pause();}});
$('stagesBtn').onclick=showStages;$('resultStagesBtn').onclick=showStages;$('closeStages').onclick=closeStages;$('stageDialog').addEventListener('cancel',e=>{e.preventDefault();closeStages();});$('accountBtn').onclick=showAccount;$('closeAccount').onclick=closeAccount;$('accountDialog').addEventListener('cancel',e=>{e.preventDefault();closeAccount();});$('accountForm').onsubmit=submitAccount;$('logoutBtn').onclick=()=>{logoutAccount();accountResume=false;$('accountDialog').close();switchProfile(null);};document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{if(!accountBusy){accountMode=b.dataset.authMode;renderAccount();}});renderAccountBadge();$('continueRunBtn').onclick=continueRun;$('practiceBoss').replaceChildren(...BOSSES.map((b,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(i+1).padStart(2,'0')+' '+b.name;return o;}));renderContinue();
new ResizeObserver(()=>renderer.resize()).observe($('arena'));renderer.resize();setMode(selected);updateSound();hud();
function frame(now){let elapsed=Math.min((now-last)/1000,.1);last=now;if(active&&!paused&&game.state==='playing'&&!document.hidden){accumulator+=elapsed;for(let n=0;accumulator>=1/60&&n<6;n++){game.update(1/60,input());accumulator-=1/60;handleEvents();if(game.state!=='playing')break;}}else accumulator=0;uiTimer+=elapsed;if(uiTimer>.07){hud();uiTimer=0;}renderer.draw(game,now,input());requestAnimationFrame(frame);}last=performance.now();requestAnimationFrame(frame);
